import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type AstronautAnimationProps = Record<string, any>;

const AstronautAnimation: React.FC<AstronautAnimationProps> = ({
  backgroundColor = "#1f2b42",
  transparentBackground = false,
  durationInSeconds = 10,
  suitColor = "#ffffff",
  visorColor = "#111115",
  badgeColor = "#ffaa00",
  badgeText = "SPACEYNAUT",
  floatSpeed = 1.0,
}) => {
  useFontLoader(["Fredoka"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Physics
  const entranceScale = spring({
    fps,
    frame,
    config: { damping: 14, mass: 0.8, stiffness: 80 },
    durationInFrames: 45,
  });

  // Landing Physics (Starts after entrance)
  const landingProgress = spring({
    fps,
    frame: Math.max(0, frame - 70),
    config: { damping: 12, mass: 1, stiffness: 50 },
  });

  // Smoothly damp floating and wiggling out as astronaut lands
  const floatAmplitude = interpolate(landingProgress, [0, 1], [40, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const rotationAmplitude = interpolate(landingProgress, [0, 1], [6, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const limbDamp = interpolate(landingProgress, [0, 1], [1, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  // Landing visual impacts
  const earthRiseY = interpolate(landingProgress, [0, 1], [800, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const starsParallax = interpolate(landingProgress, [0, 1], [0, -60], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const squash = Math.sin(landingProgress * Math.PI) * 0.05; // Adds a slight squash and stretch exactly on impact

  // Floating Motion (Dynamic amplitude based on landing status)
  const floatY = Math.sin((frame * floatSpeed) / 20) * floatAmplitude;
  const floatRotation = Math.cos((frame * floatSpeed) / 25) * rotationAmplitude;

  // Limb Wiggles (Damped on landing)
  const leftArmRot = Math.sin((frame * floatSpeed) / 18) * 12 * limbDamp;
  const rightArmRot = Math.cos((frame * floatSpeed) / 22) * 10 * limbDamp;
  const leftLegRot = Math.sin((frame * floatSpeed) / 25) * 8 * limbDamp;
  const rightLegRot = Math.cos((frame * floatSpeed) / 20) * 8 * limbDamp;

  // Static Configuration
  const strokeColor = "#1c1c21";
  const strokeWidth = 14;
  const darkGrey = "#4a4d52";
  const lightGrey = "#9ca1a6";
  const shadowGrey = "#686c73";

  // Center of canvas
  const cx = width / 2;
  const cy = height / 2;

  // Earth Layout
  const earthTop = cy + 420; // Exactly touching the astronaut's boots
  const earthCy = earthTop + 1200;
  const earthRy = 1200;
  const earthRx = width * 1.5;

  // Stars Layout
  const stars = useMemo(() => [
    { x: width * 0.15, y: height * 0.2, delay: 0, scale: 1 },
    { x: width * 0.85, y: height * 0.25, delay: 45, scale: 0.8 },
    { x: width * 0.2, y: height * 0.8, delay: 15, scale: 1.2 },
    { x: width * 0.75, y: height * 0.75, delay: 60, scale: 0.9 },
    { x: width * 0.5, y: height * 0.1, delay: 30, scale: 0.6 },
    { x: width * 0.9, y: height * 0.6, delay: 70, scale: 1.1 },
    { x: width * 0.1, y: height * 0.5, delay: 20, scale: 0.7 },
  ], [width, height]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <svg 
        width="100%" 
        height="100%" 
        viewBox={`0 0 ${width} ${height}`} 
        style={{ overflow: "visible", transition: "none" }}
      >
        {/* Stars Background */}
        <g id="stars" transform={`translate(0, ${starsParallax})`} style={{ transition: "none" }}>
          {stars.map((star, i) => {
            const opacity = 0.3 + Math.abs(Math.sin((frame + star.delay) / 20)) * 0.7;
            return (
              <g 
                key={i} 
                transform={`translate(${star.x}, ${star.y}) scale(${star.scale})`} 
                style={{ opacity, transition: "none" }}
              >
                <path 
                  d="M 0 -20 Q 0 0 20 0 Q 0 0 0 20 Q 0 0 -20 0 Q 0 0 0 -20 Z" 
                  fill="#ffffff" 
                />
              </g>
            );
          })}
        </g>

        {/* Earth Element */}
        <g id="earth" transform={`translate(0, ${earthRiseY})`} style={{ transition: "none" }}>
          <defs>
            <clipPath id="earth-clip">
              <ellipse cx={cx} cy={earthCy} rx={earthRx} ry={earthRy} />
            </clipPath>
          </defs>
          
          {/* Surface & Continents */}
          <g clipPath="url(#earth-clip)">
            {/* Ocean */}
            <ellipse cx={cx} cy={earthCy} rx={earthRx} ry={earthRy} fill="#2c5270" />
            {/* Left Continent */}
            <ellipse cx={cx - 250} cy={earthTop + 120} rx={400} ry={160} fill="#4a7c59" />
            {/* Right Continent */}
            <ellipse cx={cx + 380} cy={earthTop + 190} rx={480} ry={220} fill="#4a7c59" />
            {/* Atmosphere Highlight */}
            <path 
              d={`M 0 ${earthTop + 30} Q ${cx} ${earthTop - 20} ${width} ${earthTop + 30}`} 
              fill="none" stroke="#ffffff" strokeWidth="25" opacity="0.15" 
            />
          </g>

          {/* Earth Outline */}
          <ellipse 
            cx={cx} cy={earthCy} rx={earthRx} ry={earthRy} 
            fill="none" stroke={strokeColor} strokeWidth={strokeWidth} 
          />
        </g>

        {/* Astronaut Composition */}
        <g 
          id="astronaut" 
          // Squash is applied, but counteracted by Y translation so feet stay perfectly planted
          transform={`translate(${cx}, ${cy}) translate(0, ${floatY + (squash * 420)}) rotate(${floatRotation}) scale(${entranceScale + squash}, ${entranceScale - squash})`}
          style={{ transition: "none" }}
        >
          {/* Backpack Shadow (Right side depth) */}
          <rect 
            x="-120" y="-170" width="300" height="420" rx="50" 
            fill={shadowGrey} stroke={strokeColor} strokeWidth={strokeWidth} 
            strokeLinejoin="round" 
          />
          {/* Backpack Main */}
          <rect 
            x="-160" y="-180" width="300" height="420" rx="50" 
            fill={lightGrey} stroke={strokeColor} strokeWidth={strokeWidth} 
            strokeLinejoin="round" 
          />
          {/* Backpack Details */}
          <path 
            d="M 90 -120 L 90 100" 
            stroke={shadowGrey} strokeWidth="16" strokeLinecap="round" 
          />

          {/* Left Arm (Pivot at shoulder: -100, -20) */}
          <g transform={`rotate(${leftArmRot} -100 -20)`} style={{ transition: "none" }}>
            <path 
              d="M -100 -20 Q -220 -140 -260 -60 L -230 -20 Q -150 20 -100 40 Z" 
              fill={suitColor} stroke={strokeColor} strokeWidth={strokeWidth} strokeLinejoin="round" 
            />
            {/* Left Glove */}
            <ellipse 
              cx="-250" cy="-40" rx="28" ry="45" transform="rotate(45 -250 -40)" 
              fill={darkGrey} stroke={strokeColor} strokeWidth={strokeWidth} 
            />
          </g>

          {/* Right Arm (Pivot at shoulder: 100, -20) */}
          <g transform={`rotate(${rightArmRot} 100 -20)`} style={{ transition: "none" }}>
            <path 
              d="M 100 -20 Q 220 20 270 90 L 230 130 Q 150 70 100 40 Z" 
              fill={suitColor} stroke={strokeColor} strokeWidth={strokeWidth} strokeLinejoin="round" 
            />
            {/* Right Glove */}
            <ellipse 
              cx="255" cy="110" rx="28" ry="45" transform="rotate(-35 255 110)" 
              fill={darkGrey} stroke={strokeColor} strokeWidth={strokeWidth} 
            />
          </g>

          {/* Left Leg (Pivot at hip: -60, 160) */}
          <g transform={`rotate(${leftLegRot} -60 160)`} style={{ transition: "none" }}>
            <path 
              d="M -60 160 Q -110 280 -140 340 L -70 360 Q -30 270 0 160 Z" 
              fill={suitColor} stroke={strokeColor} strokeWidth={strokeWidth} strokeLinejoin="round" 
            />
            {/* Left Boot */}
            <path 
              d="M -150 330 Q -180 390 -110 410 L -60 370 Z" 
              fill={darkGrey} stroke={strokeColor} strokeWidth={strokeWidth} strokeLinejoin="round" 
            />
            <path d="M -135 355 L -80 375" stroke={strokeColor} strokeWidth="10" strokeLinecap="round" />
            <path d="M -130 380 L -85 400" stroke={strokeColor} strokeWidth="10" strokeLinecap="round" />
          </g>

          {/* Right Leg (Pivot at hip: 60, 160) */}
          <g transform={`rotate(${rightLegRot} 60 160)`} style={{ transition: "none" }}>
            <path 
              d="M 60 160 Q 20 270 -10 350 L 50 380 Q 100 270 120 160 Z" 
              fill={suitColor} stroke={strokeColor} strokeWidth={strokeWidth} strokeLinejoin="round" 
            />
            {/* Right Boot */}
            <path 
              d="M -20 340 Q -30 410 40 420 L 70 380 Z" 
              fill={darkGrey} stroke={strokeColor} strokeWidth={strokeWidth} strokeLinejoin="round" 
            />
            <path d="M -5 365 L 50 390" stroke={strokeColor} strokeWidth="10" strokeLinecap="round" />
            <path d="M 5 390 L 55 410" stroke={strokeColor} strokeWidth="10" strokeLinecap="round" />
          </g>

          {/* Main Body */}
          <rect 
            x="-130" y="-80" width="260" height="290" rx="100" 
            fill={suitColor} stroke={strokeColor} strokeWidth={strokeWidth} 
          />

          {/* Harness System */}
          <g id="harness">
            {/* Left Shoulder Strap */}
            <rect 
              x="-95" y="-90" width="35" height="230" rx="17" 
              fill={darkGrey} stroke={strokeColor} strokeWidth={strokeWidth} 
              transform="rotate(10 -75 20)" 
            />
            {/* Right Shoulder Strap */}
            <rect 
              x="60" y="-90" width="35" height="230" rx="17" 
              fill={darkGrey} stroke={strokeColor} strokeWidth={strokeWidth} 
              transform="rotate(-10 75 20)" 
            />
            
            {/* Horizontal Belt */}
            <rect 
              x="-125" y="130" width="250" height="50" rx="15" 
              fill={darkGrey} stroke={strokeColor} strokeWidth={strokeWidth} 
            />
            
            {/* Center Buckle */}
            <polygon 
              points="-45,115 45,115 55,155 45,195 -45,195 -55,155" 
              fill={lightGrey} stroke={strokeColor} strokeWidth={strokeWidth} strokeLinejoin="round"
            />
            <circle cx="0" cy="155" r="18" fill={darkGrey} stroke={strokeColor} strokeWidth="10" />
          </g>

          {/* Chest Badge */}
          <g transform="translate(0, 15) rotate(-6)" id="badge">
            <rect 
              x="-80" y="-22" width="160" height="44" rx="12" 
              fill={badgeColor} stroke={strokeColor} strokeWidth={strokeWidth} 
            />
            <text 
              x="0" y="6" 
              fontFamily="Fredoka" fontSize="22" fontWeight="900" 
              fill={strokeColor} textAnchor="middle" letterSpacing="2"
              style={{ transition: "none" }}
            >
              {badgeText}
            </text>
          </g>

          {/* Helmet Assembly */}
          <g id="helmet">
            {/* Helmet Base/Back */}
            <rect 
              x="-145" y="-220" width="290" height="250" rx="125" 
              fill={suitColor} stroke={strokeColor} strokeWidth={strokeWidth} 
            />
            
            {/* Helmet Side Modules */}
            {/* Left Module */}
            <rect 
              x="-165" y="-150" width="45" height="80" rx="20" 
              fill={lightGrey} stroke={strokeColor} strokeWidth={strokeWidth} 
            />
            <circle cx="-142" cy="-110" r="12" fill={strokeColor} />
            
            {/* Right Module */}
            <rect 
              x="120" y="-150" width="45" height="80" rx="20" 
              fill={lightGrey} stroke={strokeColor} strokeWidth={strokeWidth} 
            />
            <path 
              d="M 142 -130 L 142 -90" 
              stroke={strokeColor} strokeWidth="10" strokeLinecap="round" 
            />

            {/* Visor Frame */}
            <rect 
              x="-125" y="-195" width="250" height="200" rx="100" 
              fill="#e6e8eb" stroke={strokeColor} strokeWidth={strokeWidth} 
            />
            
            {/* Visor Glass (Black Area) */}
            <rect 
              x="-105" y="-175" width="210" height="160" rx="80" 
              fill={visorColor} stroke={strokeColor} strokeWidth="10" 
            />
            
            {/* Visor Reflection Gloss */}
            <path 
              d="M -60 -120 Q -30 -165 20 -130" 
              stroke="#ffffff" strokeWidth="28" strokeLinecap="round" fill="none" 
            />
            <circle cx="45" cy="-105" r="10" fill="#ffffff" />
          </g>
          
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default AstronautAnimation;